# -*- coding: utf-8 -*-
"""Assembled Simulators for Class 4 Science Chapter 10"""

simulators = {
    'sim_daily_sky_cycle': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-amber-300">24-Hour Diurnal Sky & Solar Arc Simulator</h3>\n                <p class="text-xs text-slate-400">Slide the time of day to observe atmospheric light, color gradients, and solar position shifts.</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <span class="text-xs text-slate-400">Time: <b id="timeDisplayVal" class="text-amber-400">06:00 AM (Dawn)</b></span>\n                <input type="range" id="dailyTimeSlider" min="0" max="24" value="6" step="1" oninput="updateDailySkyTime(this.value)" class="w-28 sm:w-36 accent-amber-500">\n            </div>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-12 gap-4 items-center">\n            <!-- Sky Canvas / SVG View -->\n            <div class="md:col-span-8 bg-slate-950 rounded-xl p-3 border border-slate-800 relative overflow-hidden min-h-[220px]">\n                <svg viewBox="0 0 500 220" class="w-full h-auto">\n                    <!-- Sky Background with dynamic gradient fill -->\n                    <rect id="skyBackgroundRect" x="0" y="0" width="500" height="170" fill="#f97316" opacity="0.85"/>\n                    \n                    <!-- Celestial Sun -->\n                    <g id="celestialSunGroup" transform="translate(60, 140)">\n                        <circle cx="0" cy="0" r="18" fill="#fbbf24" filter="drop-shadow(0 0 8px #f59e0b)"/>\n                        <circle cx="0" cy="0" r="24" fill="#fef08a" opacity="0.3"/>\n                    </g>\n\n                    <!-- Celestial Moon & Stars (Night) -->\n                    <g id="celestialMoonGroup" transform="translate(250, 60)" class="hidden">\n                        <circle cx="0" cy="0" r="14" fill="#e2e8f0" filter="drop-shadow(0 0 6px #cbd5e1)"/>\n                        <!-- Little stars -->\n                        <circle cx="-80" cy="-30" r="1.5" fill="#ffffff" class="animate-ping"/>\n                        <circle cx="80" cy="-20" r="1.5" fill="#ffffff"/>\n                        <circle cx="-140" cy="10" r="1.5" fill="#ffffff"/>\n                        <circle cx="140" cy="20" r="1.5" fill="#ffffff"/>\n                    </g>\n\n                    <!-- Terrestrial Horizon / Silhouette Trees -->\n                    <rect x="0" y="170" width="500" height="50" fill="#1e293b"/>\n                    <!-- Hills -->\n                    <path d="M0,170 Q120,135 240,170 T500,165 L500,220 L0,220 Z" fill="#0f172a"/>\n                    <!-- Tree silhouette -->\n                    <polygon points="120,170 135,130 150,170" fill="#1e293b"/>\n                    <polygon points="380,170 395,125 410,170" fill="#1e293b"/>\n                    \n                    <!-- Cardinal Directions -->\n                    <text x="30" y="195" fill="#94a3b8" font-size="10" font-weight="bold">EAST (Sunrise)</text>\n                    <text x="470" y="195" fill="#94a3b8" font-size="10" font-weight="bold" text-anchor="end">WEST (Sunset)</text>\n                </svg>\n\n                <div class="flex items-center justify-between text-[11px] text-slate-400 mt-2">\n                    <span id="skyPhaseDesc">🌅 Morning Dawn: Golden-orange horizon; birds awake and take flight.</span>\n                </div>\n            </div>\n\n            <!-- Diurnal Status Card -->\n            <div class="md:col-span-4 bg-slate-950 rounded-xl p-4 border border-slate-800 space-y-3">\n                <h4 class="text-xs font-bold text-amber-400 uppercase tracking-wide">Atmospheric Condition</h4>\n                <div class="space-y-2 text-xs">\n                    <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-slate-400 block text-[10px]">SOLAR ELEVATION</span>\n                        <span id="solarElevVal" class="font-bold text-amber-300">Low Slanted Angle (15°)</span>\n                    </div>\n                    <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-slate-400 block text-[10px]">ATMOSPHERIC COLOR</span>\n                        <span id="skyColorVal" class="font-semibold text-orange-400">Golden Amber & Soft Rose</span>\n                    </div>\n                    <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-slate-400 block text-[10px]">NATURE BEHAVIOR</span>\n                        <span id="natureActVal" class="font-semibold text-emerald-400">Songbirds singing, flowers opening</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_solar_radiance': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-amber-300">The Sun: Planetary Powerhouse & Core Fusion</h3>\n                <p class="text-xs text-slate-400">Explore solar energy generation, nuclear fusion in the core, and radiation reaching planet Earth.</p>\n            </div>\n            <button onclick="triggerSolarFlare()" class="px-3 py-1.5 rounded-xl bg-amber-500 hover:bg-amber-400 text-slate-950 font-bold text-xs transition flex items-center gap-1">\n                <span>⚡</span> Release Solar Flare\n            </button>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-2 gap-4 items-center">\n            <!-- Cutaway Solar Core Diagram -->\n            <div class="bg-slate-950 rounded-xl p-4 border border-slate-800 flex flex-col items-center justify-center min-h-[220px] relative">\n                <div class="relative w-44 h-44 rounded-full bg-gradient-to-br from-amber-500 via-orange-600 to-red-700 flex items-center justify-center shadow-2xl border-2 border-yellow-400/80">\n                    <!-- Core Glow -->\n                    <div id="solarCoreGlow" class="w-20 h-20 rounded-full bg-yellow-200 flex flex-col items-center justify-center shadow-inner animate-pulse">\n                        <span class="text-[9px] font-bold text-amber-950">CORE</span>\n                        <span class="text-[8px] text-amber-900">15,000,000°C</span>\n                    </div>\n                    <!-- Radiation Streamers -->\n                    <div class="absolute -top-3 w-2 h-6 bg-yellow-300 rounded-full blur-[1px]"></div>\n                    <div class="absolute -bottom-3 w-2 h-6 bg-yellow-300 rounded-full blur-[1px]"></div>\n                    <div class="absolute -left-3 w-6 h-2 bg-yellow-300 rounded-full blur-[1px]"></div>\n                    <div class="absolute -right-3 w-6 h-2 bg-yellow-300 rounded-full blur-[1px]"></div>\n                </div>\n                <span class="text-[11px] text-amber-300 font-bold mt-3">Hydrogen Fusion into Helium Gas</span>\n            </div>\n\n            <!-- Solar Power Functions -->\n            <div class="bg-slate-950 rounded-xl p-4 border border-slate-800 space-y-2.5 text-xs">\n                <span class="text-xs font-bold text-amber-400 uppercase tracking-wide">Earth Life Support Engines</span>\n                \n                <div class="p-2.5 rounded-lg bg-slate-900 border border-slate-800 flex items-start gap-2">\n                    <span class="text-base">🌱</span>\n                    <div>\n                        <span class="font-bold text-emerald-300">Photosynthesis Engine</span>\n                        <p class="text-[11px] text-slate-300">Provides light photons for green plants to manufacture carbohydrates and produce oxygen.</p>\n                    </div>\n                </div>\n\n                <div class="p-2.5 rounded-lg bg-slate-900 border border-slate-800 flex items-start gap-2">\n                    <span class="text-base">💧</span>\n                    <div>\n                        <span class="font-bold text-cyan-300">Hydrological Water Cycle</span>\n                        <p class="text-[11px] text-slate-300">Evaporates ocean water into vapor, driving global rainfall and freshwater replenishment.</p>\n                    </div>\n                </div>\n\n                <div class="p-2.5 rounded-lg bg-slate-900 border border-slate-800 flex items-start gap-2">\n                    <span class="text-base">💨</span>\n                    <div>\n                        <span class="font-bold text-yellow-300">Atmospheric Winds</span>\n                        <p class="text-[11px] text-slate-300">Unequal solar heating creates pressure differentials, generating planetary wind currents.</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_biological_rhythms': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-emerald-300">Circadian Rhythms: Diurnal vs Nocturnal Behaviors</h3>\n                <p class="text-xs text-slate-400">Toggle between Daytime and Nighttime to observe physiological and behavioral shifts in nature.</p>\n            </div>\n            <div class="flex gap-2">\n                <button onclick="setCircadianMode(\'day\')" id="btnCircDay" class="px-3 py-1 rounded-xl bg-amber-500 text-slate-950 font-bold text-xs transition">☀️ Daytime (Diurnal)</button>\n                <button onclick="setCircadianMode(\'night\')" id="btnCircNight" class="px-3 py-1 rounded-xl bg-slate-800 text-slate-300 hover:text-white font-bold text-xs transition">🌙 Nighttime (Nocturnal)</button>\n            </div>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-3 gap-3">\n            <!-- Card 1: Flora (Sunflower / Jasmine) -->\n            <div class="bg-slate-950 rounded-xl p-3 border border-slate-800 flex flex-col justify-between space-y-2">\n                <span class="text-xs font-bold text-amber-400 uppercase tracking-wide">1. Plant Responses</span>\n                <div class="h-28 bg-slate-900 rounded-lg border border-slate-800 flex flex-col items-center justify-center">\n                    <span id="circFloraIcon" class="text-4xl transition-transform duration-500">🌻</span>\n                    <span id="circFloraTitle" class="text-xs font-bold text-amber-300 mt-1">Sunflower Heliotropism</span>\n                </div>\n                <p id="circFloraDesc" class="text-[11px] text-slate-300 leading-snug">Petals wide open, actively facing the Sun to maximize photon absorption.</p>\n            </div>\n\n            <!-- Card 2: Aviary / Birds (Sparrow vs Owl) -->\n            <div class="bg-slate-950 rounded-xl p-3 border border-slate-800 flex flex-col justify-between space-y-2">\n                <span class="text-xs font-bold text-cyan-400 uppercase tracking-wide">2. Bird Behaviors</span>\n                <div class="h-28 bg-slate-900 rounded-lg border border-slate-800 flex flex-col items-center justify-center">\n                    <span id="circBirdIcon" class="text-4xl transition-transform duration-500">🐦</span>\n                    <span id="circBirdTitle" class="text-xs font-bold text-cyan-300 mt-1">Songbirds & Honeybees</span>\n                </div>\n                <p id="circBirdDesc" class="text-[11px] text-slate-300 leading-snug">Actively flying between trees, foraging for seeds and collecting nectar.</p>\n            </div>\n\n            <!-- Card 3: Mammals (Human/Cattle vs Bat) -->\n            <div class="bg-slate-950 rounded-xl p-3 border border-slate-800 flex flex-col justify-between space-y-2">\n                <span class="text-xs font-bold text-emerald-400 uppercase tracking-wide">3. Animal Activity</span>\n                <div class="h-28 bg-slate-900 rounded-lg border border-slate-800 flex flex-col items-center justify-center">\n                    <span id="circMammalIcon" class="text-4xl transition-transform duration-500">🐄</span>\n                    <span id="circMammalTitle" class="text-xs font-bold text-emerald-300 mt-1">Farm Cattle & Humans</span>\n                </div>\n                <p id="circMammalDesc" class="text-[11px] text-slate-300 leading-snug">Grazing in pasture, farming, schooling, and outdoor agricultural tasks.</p>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_shadow_formation': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-cyan-300">Optical Shadow Formation: Material Transparency Tester</h3>\n                <p class="text-xs text-slate-400">Select different barrier materials to observe how straight light rays interact with obstacles.</p>\n            </div>\n            <div class="flex gap-1.5 flex-wrap">\n                <button onclick="setShadowMaterial(\'opaque\')" id="btnMatOpaque" class="px-2.5 py-1 text-xs rounded-lg bg-cyan-600 text-white font-bold transition">🪵 Opaque Wood</button>\n                <button onclick="setShadowMaterial(\'translucent\')" id="btnMatTranslucent" class="px-2.5 py-1 text-xs rounded-lg bg-slate-800 text-slate-300 hover:text-white font-bold transition">📜 Butter Paper</button>\n                <button onclick="setShadowMaterial(\'transparent\')" id="btnMatTransparent" class="px-2.5 py-1 text-xs rounded-lg bg-slate-800 text-slate-300 hover:text-white font-bold transition">🪟 Clear Glass</button>\n            </div>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-12 gap-4 items-center">\n            <!-- Ray Diagram SVG -->\n            <div class="md:col-span-8 bg-slate-950 rounded-xl p-3 border border-slate-800 relative overflow-hidden min-h-[220px]">\n                <svg viewBox="0 0 500 200" class="w-full h-auto">\n                    <!-- Light Source (Lamp / Torch) -->\n                    <g transform="translate(30, 80)">\n                        <rect x="0" y="10" width="35" height="20" rx="3" fill="#475569"/>\n                        <polygon points="35,5 50,0 50,40 35,35" fill="#facc15"/>\n                        <circle cx="55" cy="20" r="12" fill="#fef08a" opacity="0.6"/>\n                    </g>\n\n                    <!-- Incident Straight Rays -->\n                    <line x1="85" y1="95" x2="220" y2="60" stroke="#fef08a" stroke-width="2" stroke-dasharray="4,4"/>\n                    <line x1="85" y1="100" x2="220" y2="100" stroke="#fef08a" stroke-width="2" stroke-dasharray="4,4"/>\n                    <line x1="85" y1="105" x2="220" y2="140" stroke="#fef08a" stroke-width="2" stroke-dasharray="4,4"/>\n\n                    <!-- Material Obstacle Barrier -->\n                    <g id="materialBarrierGroup" transform="translate(220, 50)">\n                        <rect id="barrierRect" x="0" y="0" width="25" height="100" rx="4" fill="#78350f" stroke="#451a03" stroke-width="2"/>\n                        <text id="barrierLabel" x="12" y="55" fill="#ffffff" font-size="9" font-weight="bold" text-anchor="middle" transform="rotate(-90 12 55)">Opaque Wood</text>\n                    </g>\n\n                    <!-- Transmitted Rays (Dynamic) -->\n                    <g id="transmittedRaysGroup">\n                        <!-- Blocked by default -->\n                    </g>\n\n                    <!-- Projection Screen -->\n                    <rect x="440" y="20" width="10" height="160" rx="2" fill="#cbd5e1" stroke="#94a3b8"/>\n                    <text x="445" y="15" fill="#94a3b8" font-size="9" text-anchor="middle">Screen</text>\n\n                    <!-- Cast Shadow on Screen -->\n                    <rect id="castShadowRect" x="438" y="45" width="6" height="110" rx="2" fill="#0f172a" opacity="0.95"/>\n                    <text id="shadowLabel" x="420" y="105" fill="#38bdf8" font-size="9" font-weight="bold" text-anchor="end">Dark Shadow</text>\n                </svg>\n            </div>\n\n            <!-- Optical Physics Explanation -->\n            <div class="md:col-span-4 bg-slate-950 rounded-xl p-4 border border-slate-800 space-y-3">\n                <h4 class="text-xs font-bold text-cyan-400 uppercase tracking-wide">Optical Law</h4>\n                <div class="p-2.5 rounded-lg bg-slate-900 border border-slate-800 text-xs space-y-1">\n                    <span class="text-amber-300 font-bold block">Rectilinear Propagation:</span>\n                    <span id="opticsLawText" class="text-slate-300 leading-snug">\n                        Light rays travel in straight lines. Opaque wood blocks rays completely, leaving a sharp, dark shadow on the screen.\n                    </span>\n                </div>\n                <div class="p-2 rounded-lg bg-slate-900 border border-slate-800 text-[11px] text-slate-400">\n                    <span>Shadow Density: </span>\n                    <span id="shadowDensityVal" class="text-emerald-400 font-bold">100% Solid Black</span>\n                </div>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_daylong_shadows': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-amber-300">Gnomon Post: Sun Elevation & Shadow Length Simulator</h3>\n                <p class="text-xs text-slate-400">Drag the solar position across the sky to observe shadow length, orientation, and noon shrinkage.</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <span class="text-xs text-slate-400">Solar Position:</span>\n                <input type="range" id="gnomonSunSlider" min="1" max="5" value="1" oninput="updateGnomonShadow(this.value)" class="w-28 sm:w-36 accent-amber-500">\n            </div>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-12 gap-4 items-center">\n            <!-- Shadow Plane SVG -->\n            <div class="md:col-span-8 bg-slate-950 rounded-xl p-3 border border-slate-800 relative overflow-hidden min-h-[230px]">\n                <svg viewBox="0 0 500 230" class="w-full h-auto">\n                    <!-- Ground surface -->\n                    <rect x="0" y="150" width="500" height="80" fill="#334155"/>\n                    <line x1="0" y1="150" x2="500" y2="150" stroke="#64748b" stroke-width="2"/>\n\n                    <!-- East and West Labels -->\n                    <text x="30" y="170" fill="#f8fafc" font-size="10" font-weight="bold">WEST (Shadow side)</text>\n                    <text x="470" y="170" fill="#f8fafc" font-size="10" font-weight="bold" text-anchor="end">EAST (Sun side)</text>\n\n                    <!-- Vertical Gnomon Post -->\n                    <g transform="translate(250, 70)">\n                        <rect x="-4" y="0" width="8" height="80" rx="2" fill="#dc2626" stroke="#991b1b" stroke-width="2"/>\n                        <circle cx="0" cy="0" r="6" fill="#facc15"/>\n                        <text x="0" y="-10" fill="#facc15" font-size="9" font-weight="bold" text-anchor="middle">Vertical Post</text>\n                    </g>\n\n                    <!-- Moving Cast Shadow -->\n                    <ellipse id="gnomonCastShadow" cx="170" cy="152" rx="75" ry="6" fill="#0f172a" opacity="0.9"/>\n\n                    <!-- Solar Body positioned dynamically -->\n                    <g id="gnomonSunOrb" transform="translate(420, 90)">\n                        <circle cx="0" cy="0" r="16" fill="#fbbf24" filter="drop-shadow(0 0 8px #f59e0b)"/>\n                        <line x1="0" y1="0" x2="-166" y2="58" stroke="#fde047" stroke-width="1.5" stroke-dasharray="4,4" opacity="0.6"/>\n                    </g>\n                </svg>\n\n                <div class="flex items-center justify-between text-[11px] text-slate-400 mt-2">\n                    <span id="gnomonStatusText">🌅 Morning (08:00 AM): Low eastern Sun casts very long shadow toward the West.</span>\n                </div>\n            </div>\n\n            <!-- Quantitative Metrics -->\n            <div class="md:col-span-4 bg-slate-950 rounded-xl p-4 border border-slate-800 space-y-3">\n                <h4 class="text-xs font-bold text-amber-400 uppercase tracking-wide">Shadow Metrics</h4>\n                <div class="space-y-2 text-xs">\n                    <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-slate-400 block text-[10px]">SHADOW LENGTH</span>\n                        <span id="shadowLengthVal" class="font-bold text-amber-300 text-sm">Long (2.8 × Post Height)</span>\n                    </div>\n                    <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-slate-400 block text-[10px]">SHADOW DIRECTION</span>\n                        <span id="shadowDirVal" class="font-semibold text-cyan-300">Pointing West (Opposite Sun)</span>\n                    </div>\n                    <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-slate-400 block text-[10px]">SOLAR ZENITH ANGLE</span>\n                        <span id="solarZenithVal" class="font-semibold text-emerald-400">25° Elevation</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_torch_shadow_lab': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-cyan-300">Indoor Optics Lab: Torch Distance & Beam Angle</h3>\n                <p class="text-xs text-slate-400">Adjust the torch distance slider to test shadow magnification on the wall screen.</p>\n            </div>\n            <div class="flex items-center gap-2">\n                <span class="text-xs text-slate-400">Torch Distance:</span>\n                <input type="range" id="torchDistSlider" min="20" max="100" value="50" oninput="updateTorchLab(this.value)" class="w-28 sm:w-36 accent-cyan-500">\n            </div>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-2 gap-4 items-center">\n            <!-- Torch Beam View -->\n            <div class="bg-slate-950 rounded-xl p-3 border border-slate-800 relative overflow-hidden min-h-[220px]">\n                <svg viewBox="0 0 350 200" class="w-full h-auto">\n                    <!-- Light Beam Cone -->\n                    <polygon id="torchBeamCone" points="80,100 320,30 320,170" fill="#fef08a" opacity="0.25"/>\n\n                    <!-- Torch Icon -->\n                    <g id="torchSvgGroup" transform="translate(40, 85)">\n                        <rect x="0" y="8" width="30" height="14" rx="2" fill="#64748b"/>\n                        <polygon points="30,3 42,0 42,30 30,27" fill="#38bdf8"/>\n                        <circle cx="45" cy="15" r="8" fill="#fef08a" opacity="0.8"/>\n                    </g>\n\n                    <!-- Figurine Obstacle -->\n                    <g transform="translate(180, 70)">\n                        <circle cx="0" cy="10" r="8" fill="#dc2626"/>\n                        <rect x="-4" y="18" width="8" height="40" fill="#dc2626" rx="2"/>\n                        <rect x="-10" y="58" width="20" height="4" fill="#991b1b"/>\n                    </g>\n\n                    <!-- Wall Screen -->\n                    <rect x="320" y="10" width="8" height="180" fill="#cbd5e1"/>\n\n                    <!-- Projected Shadow on Wall -->\n                    <rect id="wallShadowRect" x="317" y="60" width="5" height="80" rx="2" fill="#0f172a" opacity="0.95"/>\n                </svg>\n                <div class="text-[11px] text-slate-400 text-center mt-1">\n                    <span id="torchLabStatus">Distance: 50 cm • Shadow Height: 80 mm</span>\n                </div>\n            </div>\n\n            <!-- Experimental Insights -->\n            <div class="bg-slate-950 rounded-xl p-4 border border-slate-800 space-y-3">\n                <span class="text-xs font-bold text-cyan-400 uppercase tracking-wide">Experimental Observations</span>\n                \n                <div class="space-y-2 text-xs">\n                    <div class="p-2.5 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-amber-300 font-bold block">1. Distance vs Magnification</span>\n                        <p class="text-[11px] text-slate-300">Moving torch closer intercepts wider cone angle → larger magnified shadow.</p>\n                    </div>\n\n                    <div class="p-2.5 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-cyan-300 font-bold block">2. Sharpness vs Diffusion</span>\n                        <p class="text-[11px] text-slate-300">Point light sources cast razor-sharp umbra; broad torches create soft penumbra borders.</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_sundial_astronomy': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-amber-300">Jantar Mantar: Brihat Samrat Yantra (Jaipur)</h3>\n                <p class="text-xs text-slate-400">Step the solar hour to see the 27-metre stone gnomon cast shadows across calibrated marble quadrants.</p>\n            </div>\n            <div class="flex items-center gap-1.5">\n                <button onclick="stepSundialHour(-1)" class="px-2.5 py-1 text-xs rounded-lg bg-slate-800 hover:bg-slate-700 font-bold transition">◀ -1 Hr</button>\n                <span id="sundialTimeText" class="px-3 py-1 rounded-lg bg-amber-500/20 text-amber-300 border border-amber-500/30 font-bold text-xs">12:00 PM (Noon)</span>\n                <button onclick="stepSundialHour(1)" class="px-2.5 py-1 text-xs rounded-lg bg-slate-800 hover:bg-slate-700 font-bold transition">+1 Hr ▶</button>\n            </div>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-12 gap-4 items-center">\n            <!-- Sundial SVG Graphic -->\n            <div class="md:col-span-8 bg-slate-950 rounded-xl p-3 border border-slate-800 relative overflow-hidden min-h-[230px]">\n                <svg viewBox="0 0 500 230" class="w-full h-auto">\n                    <!-- Ground base -->\n                    <rect x="0" y="190" width="500" height="40" fill="#334155"/>\n\n                    <!-- Massive Triangular Gnomon (Jaipur Samrat Yantra: 27 m tall) -->\n                    <polygon points="250,30 250,190 120,190" fill="#b45309" stroke="#78350f" stroke-width="2"/>\n                    <text x="180" y="160" fill="#fef3c7" font-size="9" font-weight="bold">Triangular Gnomon (27 m)</text>\n\n                    <!-- Curved Marble Quadrant Scale (Left & Right) -->\n                    <path d="M120,190 Q180,110 250,105" stroke="#cbd5e1" stroke-width="8" fill="none"/>\n                    <path d="M250,105 Q320,110 380,190" stroke="#cbd5e1" stroke-width="8" fill="none"/>\n                    <text x="350" y="180" fill="#94a3b8" font-size="8">Marble Scale</text>\n\n                    <!-- Moving Shadow Line on Quadrant -->\n                    <line id="sundialShadowLine" x1="250" y1="30" x2="250" y2="105" stroke="#0f172a" stroke-width="4"/>\n                </svg>\n\n                <div class="flex items-center justify-between text-[11px] text-slate-400 mt-2">\n                    <span id="sundialAccuracyText">Precision: Local solar time measured to within 2 seconds accuracy.</span>\n                    <span class="text-amber-400 font-bold">UNESCO World Heritage Site</span>\n                </div>\n            </div>\n\n            <!-- Archaeoastronomy Data -->\n            <div class="md:col-span-4 bg-slate-950 rounded-xl p-4 border border-slate-800 space-y-3">\n                <h4 class="text-xs font-bold text-amber-400 uppercase tracking-wide">Observatory Facts</h4>\n                <div class="space-y-2 text-xs">\n                    <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-slate-400 block text-[10px]">FIVE OBSERVATORY CITIES</span>\n                        <span class="font-bold text-slate-200">Jaipur, Delhi, Ujjain, Varanasi, Mathura</span>\n                    </div>\n                    <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-slate-400 block text-[10px]">GNOMON ALIGNMENT</span>\n                        <span class="font-bold text-cyan-300">Parallel to Earth\'s axis (Points to Pole Star)</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_shadow_puppetry': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-amber-300">Indian Shadow Theatre & Hand Silhouettes</h3>\n                <p class="text-xs text-slate-400">Select hand silhouettes or traditional leather puppets to project stories on the glowing screen.</p>\n            </div>\n            <div class="flex gap-1.5 flex-wrap">\n                <button onclick="setShadowPuppet(\'deer\')" id="btnPupDeer" class="px-2.5 py-1 text-xs rounded-lg bg-amber-500 text-slate-950 font-bold transition">🦌 Deer Silhouette</button>\n                <button onclick="setShadowPuppet(\'bird\')" id="btnPupBird" class="px-2.5 py-1 text-xs rounded-lg bg-slate-800 text-slate-300 hover:text-white font-bold transition">🦅 Flying Eagle</button>\n                <button onclick="setShadowPuppet(\'dog\')" id="btnPupDog" class="px-2.5 py-1 text-xs rounded-lg bg-slate-800 text-slate-300 hover:text-white font-bold transition">🐕 Barking Dog</button>\n                <button onclick="setShadowPuppet(\'tholu\')" id="btnPupTholu" class="px-2.5 py-1 text-xs rounded-lg bg-slate-800 text-slate-300 hover:text-white font-bold transition">🎭 Leather Puppet</button>\n            </div>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-2 gap-4 items-center">\n            <!-- Illuminated Cloth Screen Projection -->\n            <div class="bg-slate-950 rounded-xl p-4 border border-slate-800 flex flex-col items-center justify-center min-h-[220px]">\n                <div class="w-64 h-40 bg-gradient-to-r from-amber-100 via-yellow-50 to-amber-100 rounded-xl border-4 border-amber-700 shadow-2xl relative flex items-center justify-center overflow-hidden">\n                    <!-- Projector Backlight Glow -->\n                    <div class="absolute inset-0 bg-yellow-400/20 animate-pulse pointer-events-none"></div>\n\n                    <!-- Shadow Figure Projected -->\n                    <div id="puppetFigureDisplay" class="text-6xl text-slate-950 filter drop-shadow-md select-none transition-transform duration-300">\n                        🦌\n                    </div>\n                </div>\n                <span class="text-[11px] text-slate-400 mt-2">Backlit Translucent Cotton Screen</span>\n            </div>\n\n            <!-- Folk Art Context -->\n            <div class="bg-slate-950 rounded-xl p-4 border border-slate-800 space-y-3">\n                <span id="puppetTraditionTitle" class="text-xs font-bold text-amber-400 uppercase tracking-wide">Hand Shadow: Leaping Deer</span>\n                <p id="puppetTraditionDesc" class="text-xs text-slate-300 leading-relaxed">\n                    Created by joining wrists together with fingers extended upwards like antlers. The thumb forms the deer\'s muzzle, demonstrating hand optics.\n                </p>\n\n                <div class="p-2.5 rounded-lg bg-slate-900 border border-slate-800 space-y-1 text-xs">\n                    <span class="text-cyan-400 font-bold block">Heritage Shadow Traditions:</span>\n                    <span class="text-slate-300 block">● <b>Togalu Gombeyaata</b> (Karnataka)</span>\n                    <span class="text-slate-300 block">● <b>Tholu Bommalata</b> (Andhra Pradesh)</span>\n                    <span class="text-slate-300 block">● <b>Ravanachhaya</b> (Odisha)</span>\n                </div>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_night_stargazing': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-indigo-300">Constellation Astronomy: Saptarishi & Polaris (Pole Star)</h3>\n                <p class="text-xs text-slate-400">Identify the seven stars of Saptarishi (Ursa Major) and trace the pointer stars directly to Polaris.</p>\n            </div>\n            <button onclick="toggleConstellationLines()" id="btnConstLines" class="px-3 py-1.5 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-xs transition">\n                ✨ Connect Saptarishi Stars\n            </button>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-12 gap-4 items-center">\n            <!-- Starlight SVG Canvas -->\n            <div class="md:col-span-8 bg-slate-950 rounded-xl p-3 border border-slate-800 relative overflow-hidden min-h-[230px]">\n                <svg viewBox="0 0 500 230" class="w-full h-auto">\n                    <!-- Deep Velvet Night Sky with Ambient Stars -->\n                    <rect x="0" y="0" width="500" height="230" fill="#030712"/>\n                    \n                    <!-- Random Twinkling Background Stars -->\n                    <circle cx="40" cy="50" r="1.5" fill="#ffffff" opacity="0.6"/>\n                    <circle cx="90" cy="180" r="1" fill="#ffffff" opacity="0.4"/>\n                    <circle cx="160" cy="30" r="1.5" fill="#ffffff" opacity="0.5"/>\n                    <circle cx="280" cy="40" r="1" fill="#ffffff" opacity="0.4"/>\n                    <circle cx="440" cy="70" r="1.5" fill="#ffffff" opacity="0.6"/>\n                    <circle cx="470" cy="190" r="1" fill="#ffffff" opacity="0.5"/>\n\n                    <!-- Saptarishi (7 Stars of the Ladle) -->\n                    <!-- Handle: 1, 2, 3 -->\n                    <circle id="star1" cx="80" cy="150" r="3.5" fill="#67e8f9" filter="drop-shadow(0 0 4px #06b6d4)"/>\n                    <circle id="star2" cx="130" cy="130" r="3.5" fill="#67e8f9" filter="drop-shadow(0 0 4px #06b6d4)"/>\n                    <circle id="star3" cx="180" cy="135" r="3.5" fill="#67e8f9" filter="drop-shadow(0 0 4px #06b6d4)"/>\n                    <!-- Bowl: 4, 5, 6, 7 -->\n                    <circle id="star4" cx="220" cy="160" r="3.5" fill="#67e8f9" filter="drop-shadow(0 0 4px #06b6d4)"/>\n                    <circle id="star5" cx="280" cy="165" r="4" fill="#a5f3fc" filter="drop-shadow(0 0 6px #22d3ee)"/>\n                    <circle id="star6" cx="290" cy="115" r="4" fill="#a5f3fc" filter="drop-shadow(0 0 6px #22d3ee)"/>\n                    <circle id="star7" cx="225" cy="110" r="3.5" fill="#67e8f9" filter="drop-shadow(0 0 4px #06b6d4)"/>\n\n                    <!-- Polaris (North Pole Star) -->\n                    <circle id="starPolaris" cx="305" cy="35" r="5" fill="#facc15" filter="drop-shadow(0 0 8px #eab308)"/>\n                    <text x="320" y="38" fill="#fef08a" font-size="10" font-weight="bold">Polaris (Dhruva Tara)</text>\n\n                    <!-- Constellation Stick Lines (Dynamic) -->\n                    <g id="constellationLinesGroup" class="hidden">\n                        <line x1="80" y1="150" x2="130" y2="130" stroke="#06b6d4" stroke-width="1.5" stroke-dasharray="3,3"/>\n                        <line x1="130" y1="130" x2="180" y2="135" stroke="#06b6d4" stroke-width="1.5" stroke-dasharray="3,3"/>\n                        <line x1="180" y1="135" x2="220" y2="160" stroke="#06b6d4" stroke-width="1.5" stroke-dasharray="3,3"/>\n                        <line x1="220" y1="160" x2="280" y2="165" stroke="#06b6d4" stroke-width="1.5" stroke-dasharray="3,3"/>\n                        <line x1="280" y1="165" x2="290" y2="115" stroke="#06b6d4" stroke-width="2"/>\n                        <line x1="290" y1="115" x2="225" y2="110" stroke="#06b6d4" stroke-width="1.5" stroke-dasharray="3,3"/>\n                        <line x1="225" y1="110" x2="220" y2="160" stroke="#06b6d4" stroke-width="1.5" stroke-dasharray="3,3"/>\n                        <!-- Pointer Line from Star 5 & 6 to Polaris -->\n                        <line x1="290" y1="115" x2="305" y2="35" stroke="#facc15" stroke-width="2" stroke-dasharray="4,4"/>\n                    </g>\n                </svg>\n\n                <div class="flex items-center justify-between text-[11px] text-slate-400 mt-2">\n                    <span id="stargazingStatusText">Saptarishi (7 Sage Stars) pointing directly to the northern celestial pole.</span>\n                </div>\n            </div>\n\n            <!-- Stargazing Guide -->\n            <div class="md:col-span-4 bg-slate-950 rounded-xl p-4 border border-slate-800 space-y-3">\n                <h4 class="text-xs font-bold text-indigo-400 uppercase tracking-wide">Navigational Science</h4>\n                <div class="space-y-2 text-xs">\n                    <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-slate-400 block text-[10px]">POINTER STARS (Merak & Dubhe)</span>\n                        <span class="font-bold text-cyan-300">Outer two bowl stars align with North Pole Star</span>\n                    </div>\n                    <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-slate-400 block text-[10px]">ATMOSPHERIC TWINKLING</span>\n                        <span class="font-semibold text-slate-200">Refraction through shifting air densities</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_moon_surface': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-slate-200">The Moon: Cosmic Mirror & Lunar Geology</h3>\n                <p class="text-xs text-slate-400">Discover how sunlight reflects off the airless lunar surface, revealing ancient maria plains and impact craters.</p>\n            </div>\n            <button onclick="toggleSunbeamReflection()" class="px-3 py-1.5 rounded-xl bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-xs transition">\n                ☀️ Shine Sunbeam on Moon\n            </button>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-2 gap-4 items-center">\n            <!-- Moon Close-up Surface Graphic -->\n            <div class="bg-slate-950 rounded-xl p-4 border border-slate-800 flex flex-col items-center justify-center min-h-[220px]">\n                <div class="relative w-40 h-40 rounded-full bg-slate-300 border-4 border-slate-400 shadow-2xl overflow-hidden flex items-center justify-center">\n                    <!-- Maria (Dark Basalt Plains) -->\n                    <circle cx="35" cy="50" r="18" fill="#64748b" opacity="0.6"/>\n                    <circle cx="80" cy="90" r="28" fill="#475569" opacity="0.7"/>\n                    <circle cx="115" cy="45" r="15" fill="#64748b" opacity="0.6"/>\n\n                    <!-- Impact Craters -->\n                    <circle cx="60" cy="35" r="6" fill="#94a3b8" stroke="#334155" stroke-width="1.5"/>\n                    <circle cx="120" cy="110" r="8" fill="#94a3b8" stroke="#334155" stroke-width="1.5"/>\n                    <circle cx="45" cy="120" r="5" fill="#94a3b8" stroke="#334155" stroke-width="1.5"/>\n\n                    <!-- Reflected Ray Overlay -->\n                    <div id="moonReflectOverlay" class="absolute inset-0 bg-yellow-200/20 opacity-0 transition-opacity duration-700 pointer-events-none"></div>\n                </div>\n                <span class="text-[11px] text-slate-400 mt-2">Distance from Earth: 384,400 km</span>\n            </div>\n\n            <!-- Geology Facts -->\n            <div class="bg-slate-950 rounded-xl p-4 border border-slate-800 space-y-2.5 text-xs">\n                <span class="text-xs font-bold text-cyan-400 uppercase tracking-wide">Lunar Characteristics</span>\n                <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                    <span class="text-slate-400 block text-[10px]">NON-LUMINOUS REFLECTOR</span>\n                    <span class="font-bold text-yellow-300">Emits 0% own light; reflects ~12% incident sunlight</span>\n                </div>\n                <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                    <span class="text-slate-400 block text-[10px]">ZERO WEATHER EROSION</span>\n                    <span class="font-semibold text-slate-200">No air or water; impact craters preserved billions of years</span>\n                </div>\n                <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                    <span class="text-slate-400 block text-[10px]">LUNAR MARIA</span>\n                    <span class="font-semibold text-slate-200">Ancient solidified basaltic volcanic lava flows</span>\n                </div>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_lunar_phases': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-cyan-300">29.5-Day Lunar Phase Cycle: Amavasya to Poornima</h3>\n                <p class="text-xs text-slate-400">Step through the 8 distinct phases to see how orbital alignment creates changing visible shapes.</p>\n            </div>\n            <div class="flex items-center gap-1.5">\n                <button onclick="stepMoonPhase(-1)" class="px-2.5 py-1 text-xs rounded-lg bg-slate-800 hover:bg-slate-700 font-bold transition">◀ Prev</button>\n                <span id="phaseDisplayBadge" class="px-3 py-1 rounded-lg bg-cyan-500/20 text-cyan-300 border border-cyan-500/30 font-bold text-xs">1. New Moon (Amavasya)</span>\n                <button onclick="stepMoonPhase(1)" class="px-2.5 py-1 text-xs rounded-lg bg-slate-800 hover:bg-slate-700 font-bold transition">Next ▶</button>\n            </div>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-2 gap-4 items-center">\n            <!-- Earth View Display -->\n            <div class="bg-slate-950 rounded-xl p-4 border border-slate-800 flex flex-col items-center justify-center min-h-[220px]">\n                <div id="lunarPhaseVisual" class="text-7xl select-none filter drop-shadow-lg transition-transform duration-300">\n                    🌑\n                </div>\n                <span id="lunarPhaseName" class="text-sm font-bold text-cyan-300 mt-3">🌑 New Moon (Amavasya)</span>\n                <span id="lunarPhaseDay" class="text-[11px] text-slate-400">Day 1 of 29.5-day cycle</span>\n            </div>\n\n            <!-- Orbital Alignment Explanation -->\n            <div class="bg-slate-950 rounded-xl p-4 border border-slate-800 space-y-3">\n                <span class="text-xs font-bold text-cyan-400 uppercase tracking-wide">Orbital Geometry</span>\n                <p id="lunarPhaseDesc" class="text-xs text-slate-300 leading-relaxed">\n                    The Moon lies directly between the Earth and the Sun. Its illuminated hemisphere faces away into space, rendering the Moon completely invisible from Earth.\n                </p>\n\n                <div class="space-y-1.5 text-xs pt-1 border-t border-slate-800">\n                    <div class="flex justify-between">\n                        <span class="text-slate-400">Visible Illumination:</span>\n                        <span id="lunarIllumVal" class="text-emerald-400 font-bold">0% (Completely Dark)</span>\n                    </div>\n                    <div class="flex justify-between">\n                        <span class="text-slate-400">Lunar Month Progress:</span>\n                        <span id="lunarProgressVal" class="text-cyan-400 font-bold">Beginning of Cycle</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_lunar_festivals': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-amber-300">Lunar Calendar Chronometry & Indian Festivals</h3>\n                <p class="text-xs text-slate-400">Select a national festival to reveal its corresponding Moon phase and cultural significance.</p>\n            </div>\n            <div class="flex gap-1.5 flex-wrap">\n                <button onclick="selectFestival(\'diwali\')" id="btnFestDiwali" class="px-2.5 py-1 text-xs rounded-lg bg-amber-500 text-slate-950 font-bold transition">🪔 Diwali</button>\n                <button onclick="selectFestival(\'eid\')" id="btnFestEid" class="px-2.5 py-1 text-xs rounded-lg bg-slate-800 text-slate-300 hover:text-white font-bold transition">🌙 Eid</button>\n                <button onclick="selectFestival(\'buddha\')" id="btnFestBuddha" class="px-2.5 py-1 text-xs rounded-lg bg-slate-800 text-slate-300 hover:text-white font-bold transition">🌕 Buddha Poornima</button>\n                <button onclick="selectFestival(\'karva\')" id="btnFestKarva" class="px-2.5 py-1 text-xs rounded-lg bg-slate-800 text-slate-300 hover:text-white font-bold transition">✨ Karva Chauth</button>\n            </div>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-2 gap-4 items-center">\n            <!-- Festival Visual Box -->\n            <div class="bg-slate-950 rounded-xl p-4 border border-slate-800 flex flex-col items-center justify-center min-h-[200px]">\n                <div id="festEmojiIcon" class="text-6xl mb-2">🪔</div>\n                <span id="festNameHeading" class="text-base font-bold text-amber-300">Diwali (Festival of Lights)</span>\n                <span id="festPhaseTag" class="text-xs px-2.5 py-0.5 rounded-full bg-slate-800 text-slate-300 border border-slate-700 mt-1">Kartik Amavasya (New Moon)</span>\n            </div>\n\n            <!-- Cultural Chronometry Details -->\n            <div class="bg-slate-950 rounded-xl p-4 border border-slate-800 space-y-3">\n                <span class="text-xs font-bold text-amber-400 uppercase tracking-wide">Calendar Alignment</span>\n                <p id="festDescText" class="text-xs text-slate-300 leading-relaxed">\n                    Celebrated on the darkest night of the autumn month of Kartik. The complete absence of moonlight is countered by lighting millions of earthen diyas, celebrating light over darkness.\n                </p>\n                <div class="p-2.5 rounded-lg bg-slate-900 border border-slate-800 text-xs">\n                    <span class="text-cyan-400 font-bold block">Astronomical Link:</span>\n                    <span id="festAstroLink" class="text-slate-300">Nocturnal illumination is zero; maximum contrast for oil lamps and fireworks.</span>\n                </div>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_chandrayaan_landing': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-emerald-300">Chandrayaan-3: Vikram Lander Touchdown (Aug 23, 2023)</h3>\n                <p class="text-xs text-slate-400">Fire the liquid retro-rockets to counteract lunar gravity and execute a soft touchdown on 4 shock-absorbing legs.</p>\n            </div>\n            <button onclick="executeVikramLanding()" id="btnLandVikram" class="px-3 py-1.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs transition flex items-center gap-1.5">\n                <span>🚀</span> Fire Retro-Rockets\n            </button>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-12 gap-4 items-center">\n            <!-- Lunar Descent Canvas -->\n            <div class="md:col-span-8 bg-slate-950 rounded-xl p-3 border border-slate-800 relative overflow-hidden min-h-[240px]">\n                <svg viewBox="0 0 500 240" class="w-full h-auto">\n                    <!-- Black Lunar Sky -->\n                    <rect x="0" y="0" width="500" height="240" fill="#030712"/>\n\n                    <!-- Distant Earth in sky -->\n                    <circle cx="430" cy="40" r="16" fill="#0284c7" stroke="#38bdf8" stroke-width="2"/>\n                    <text x="430" y="65" fill="#94a3b8" font-size="8" text-anchor="middle">Earth</text>\n\n                    <!-- Lunar South Pole Surface with Craters -->\n                    <path d="M0,190 Q120,175 250,195 T500,185 L500,240 L0,240 Z" fill="#475569"/>\n                    <circle cx="120" cy="210" r="14" fill="#334155"/>\n                    <circle cx="380" cy="215" r="18" fill="#334155"/>\n                    <text x="250" y="230" fill="#cbd5e1" font-size="10" font-weight="bold" text-anchor="middle">Shiv Shakti Point (Lunar South Pole)</text>\n\n                    <!-- Vikram Lander Module -->\n                    <g id="vikramLanderGroup" transform="translate(225, 30)" class="transition-transform duration-1000">\n                        <!-- Gold insulated body -->\n                        <rect x="0" y="10" width="50" height="35" rx="3" fill="#eab308" stroke="#ca8a04" stroke-width="2"/>\n                        <!-- Solar panels on sides -->\n                        <polygon points="-8,15 0,15 0,40 -8,40" fill="#2563eb"/>\n                        <polygon points="50,15 58,15 58,40 50,40" fill="#2563eb"/>\n                        <!-- Top Antenna -->\n                        <line x1="25" y1="10" x2="25" y2="0" stroke="#cbd5e1" stroke-width="2"/>\n                        <circle cx="25" cy="0" r="3" fill="#cbd5e1"/>\n                        <!-- 4 Shock-absorbing landing legs -->\n                        <line x1="5" y1="45" x2="-5" y2="65" stroke="#94a3b8" stroke-width="3"/>\n                        <circle cx="-5" cy="65" r="4" fill="#64748b"/>\n                        <line x1="45" y1="45" x2="55" y2="65" stroke="#94a3b8" stroke-width="3"/>\n                        <circle cx="55" cy="65" r="4" fill="#64748b"/>\n                        <!-- Retro-rocket plume (dynamic) -->\n                        <polygon id="retroRocketPlume" points="20,45 25,68 30,45" fill="#f97316" class="hidden animate-ping"/>\n                    </g>\n                </svg>\n\n                <div class="flex items-center justify-between text-[11px] text-slate-400 mt-2">\n                    <span id="vikramStatusText">Altitude: 800 m • Descent Velocity: 45 m/s</span>\n                    <span class="text-emerald-400 font-bold">National Space Day (August 23)</span>\n                </div>\n            </div>\n\n            <!-- Touchdown Metrics -->\n            <div class="md:col-span-4 bg-slate-950 rounded-xl p-4 border border-slate-800 space-y-3">\n                <h4 class="text-xs font-bold text-emerald-400 uppercase tracking-wide">Touchdown Telemetry</h4>\n                <div class="space-y-2 text-xs">\n                    <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-slate-400 block text-[10px]">HISTORIC GLOBAL RANK</span>\n                        <span class="font-bold text-yellow-300">1st at Lunar South Pole (4th on Moon)</span>\n                    </div>\n                    <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-slate-400 block text-[10px]">BRAKING SYSTEM</span>\n                        <span class="font-bold text-cyan-300">4 Throttleable Liquid Engines (No Parachutes)</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_pragyan_rover': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-cyan-300">Pragyan Rover: Surface Exploration & Laser Spectroscopy</h3>\n                <p class="text-xs text-slate-400">Drive the 6-wheeled robotic rover, emboss wheel emblems into regolith, and fire the LIBS laser to detect sulfur.</p>\n            </div>\n            <div class="flex gap-2">\n                <button onclick="drivePragyanRover()" class="px-2.5 py-1 text-xs rounded-lg bg-cyan-600 hover:bg-cyan-500 text-white font-bold transition">🚜 Drive Rover</button>\n                <button onclick="fireLaserSpectroscope()" class="px-2.5 py-1 text-xs rounded-lg bg-amber-500 hover:bg-amber-400 text-slate-950 font-bold transition">⚡ Fire LIBS Laser</button>\n            </div>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-12 gap-4 items-center">\n            <!-- Rover Driving SVG -->\n            <div class="md:col-span-8 bg-slate-950 rounded-xl p-3 border border-slate-800 relative overflow-hidden min-h-[230px]">\n                <svg viewBox="0 0 500 230" class="w-full h-auto">\n                    <!-- Lunar Ground Surface -->\n                    <rect x="0" y="160" width="500" height="70" fill="#475569"/>\n                    \n                    <!-- Wheel Track Marks with Embossed Emblems -->\n                    <g id="pragyanTracksGroup">\n                        <line x1="0" y1="185" x2="160" y2="185" stroke="#334155" stroke-width="6" stroke-dasharray="8,6"/>\n                        <text x="80" y="180" fill="#94a3b8" font-size="7">ISRO Emblem Tracks</text>\n                    </g>\n\n                    <!-- Laser Pulse Line (Dynamic) -->\n                    <line id="roverLaserBeam" x1="220" y1="140" x2="350" y2="165" stroke="#ef4444" stroke-width="2" class="hidden"/>\n                    <circle id="laserSparkDot" cx="350" cy="165" r="4" fill="#facc15" class="hidden animate-ping"/>\n\n                    <!-- Pragyan Rover Assembly -->\n                    <g id="pragyanRoverGroup" transform="translate(160, 120)" class="transition-transform duration-500">\n                        <!-- Chassis -->\n                        <rect x="0" y="10" width="50" height="22" rx="3" fill="#eab308" stroke="#ca8a04" stroke-width="1.5"/>\n                        <!-- Solar Panel (Upright) -->\n                        <polygon points="10,-5 45,-5 40,10 5,10" fill="#2563eb" stroke="#1d4ed8" stroke-width="1"/>\n                        <!-- 6 Rocker-Bogie Wheels -->\n                        <circle cx="5" cy="38" r="6" fill="#0f172a" stroke="#cbd5e1" stroke-width="2"/>\n                        <circle cx="25" cy="38" r="6" fill="#0f172a" stroke="#cbd5e1" stroke-width="2"/>\n                        <circle cx="45" cy="38" r="6" fill="#0f172a" stroke="#cbd5e1" stroke-width="2"/>\n                    </g>\n\n                    <!-- Nearby Lunar Rock -->\n                    <polygon points="340,175 355,155 375,175" fill="#334155" stroke="#64748b" stroke-width="1.5"/>\n                    <text x="360" y="190" fill="#cbd5e1" font-size="8">Basalt Rock</text>\n                </svg>\n\n                <div class="flex items-center justify-between text-[11px] text-slate-400 mt-2">\n                    <span id="pragyanStatusText">Pragyan Rover: Stationary • Ready for in-situ soil analysis.</span>\n                </div>\n            </div>\n\n            <!-- Mineral Analysis Data -->\n            <div class="md:col-span-4 bg-slate-950 rounded-xl p-4 border border-slate-800 space-y-3">\n                <h4 class="text-xs font-bold text-cyan-400 uppercase tracking-wide">Chemical Spectroscopy</h4>\n                <div class="space-y-2 text-xs">\n                    <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-slate-400 block text-[10px]">CONFIRMED ELEMENT</span>\n                        <span id="spectralResultVal" class="font-bold text-yellow-300 text-sm">Sulfur (S) Detected!</span>\n                    </div>\n                    <div class="p-2 rounded-lg bg-slate-900 border border-slate-800">\n                        <span class="text-slate-400 block text-[10px]">OTHER MINERALS</span>\n                        <span class="font-semibold text-slate-200">Aluminum, Calcium, Iron, Chromium</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_earth_rotation': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-amber-300">Earth Axial Rotation: The Science of Day & Night</h3>\n                <p class="text-xs text-slate-400">Rotate planet Earth counter-clockwise (West to East) to see why the Sun appears to transit East to West.</p>\n            </div>\n            <button onclick="rotateEarthPlanet()" class="px-3 py-1.5 rounded-xl bg-amber-500 hover:bg-amber-400 text-slate-950 font-bold text-xs transition">\n                🔄 Spin Earth (West ➔ East)\n            </button>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-2 gap-4 items-center">\n            <!-- Rotating Earth & Sunlight -->\n            <div class="bg-slate-950 rounded-xl p-4 border border-slate-800 flex flex-col items-center justify-center min-h-[220px]">\n                <div class="relative w-40 h-40 flex items-center justify-center">\n                    <!-- Stationary Sunbeam Rays from Left -->\n                    <div class="absolute -left-12 flex flex-col gap-3">\n                        <div class="w-10 h-0.5 bg-yellow-400 animate-pulse"></div>\n                        <div class="w-10 h-0.5 bg-yellow-400 animate-pulse"></div>\n                        <div class="w-10 h-0.5 bg-yellow-400 animate-pulse"></div>\n                    </div>\n\n                    <!-- Earth Globe (Split Day/Night) -->\n                    <div id="earthGlobeVisual" class="w-36 h-36 rounded-full border-2 border-cyan-400/80 shadow-2xl overflow-hidden relative transition-transform duration-700 flex">\n                        <!-- Day side (Left) -->\n                        <div class="w-1/2 h-full bg-blue-500 relative flex items-center justify-center">\n                            <span class="text-xs font-bold text-yellow-200">DAY</span>\n                        </div>\n                        <!-- Night side (Right) -->\n                        <div class="w-1/2 h-full bg-slate-950 relative flex items-center justify-center">\n                            <span class="text-xs font-bold text-slate-400">NIGHT</span>\n                        </div>\n                    </div>\n                </div>\n                <span class="text-[11px] text-cyan-300 font-bold mt-2">1 Full Rotation = 24 Hours</span>\n            </div>\n\n            <!-- Train Analogy Explanation -->\n            <div class="bg-slate-950 rounded-xl p-4 border border-slate-800 space-y-3">\n                <span class="text-xs font-bold text-cyan-400 uppercase tracking-wide">The Moving Train Analogy</span>\n                <p class="text-xs text-slate-300 leading-relaxed">\n                    When your train pulls forward out of a station, the trees and platform appear to rush backwards in reverse. Similarly, because Earth spins smoothly from <b>West to East</b>, the stationary Sun appears to move from <b>East to West</b>!\n                </p>\n                <div class="p-2.5 rounded-lg bg-slate-900 border border-slate-800 text-xs">\n                    <span class="text-amber-300 font-bold block">Scientific Truth:</span>\n                    <span class="text-slate-300">The Sun is stationary at the solar system center; Earth\'s spin creates the day-night cycle.</span>\n                </div>\n            </div>\n        </div>\n    </div>\n    ',
    'sim_sky_tracker_matrix': '\n    <div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n            <div>\n                <h3 class="text-sm font-bold text-cyan-300">Master Sky Tracker: Diurnal & Nocturnal Synthesis Matrix</h3>\n                <p class="text-xs text-slate-400">Consolidated scientific reference comparing sky color, solar altitude, shadow behavior, and living activities.</p>\n            </div>\n        </div>\n\n        <div class="overflow-x-auto">\n            <table class="w-full text-left text-xs text-slate-300 border-collapse">\n                <thead>\n                    <tr class="border-b border-slate-800 text-[11px] text-slate-400 uppercase bg-slate-950">\n                        <th class="p-2.5">Time Period</th>\n                        <th class="p-2.5 text-amber-400">Sky Appearance</th>\n                        <th class="p-2.5 text-yellow-400">Solar Position</th>\n                        <th class="p-2.5 text-cyan-400">Shadow Length & Direction</th>\n                        <th class="p-2.5 text-emerald-400">Nature Activities</th>\n                    </tr>\n                </thead>\n                <tbody class="divide-y divide-slate-800/60">\n                    <tr class="hover:bg-slate-800/40">\n                        <td class="p-2.5 font-bold text-amber-300">🌅 Morning (Dawn)</td>\n                        <td class="p-2.5">Golden amber, soft rose</td>\n                        <td class="p-2.5">Low on Eastern horizon</td>\n                        <td class="p-2.5">Very Long • Pointing West</td>\n                        <td class="p-2.5">Roosters crow, sparrows fly, flowers open</td>\n                    </tr>\n                    <tr class="hover:bg-slate-800/40">\n                        <td class="p-2.5 font-bold text-yellow-300">☀️ Midday (Noon)</td>\n                        <td class="p-2.5">Brilliant azure blue</td>\n                        <td class="p-2.5">Highest point (Zenith overhead)</td>\n                        <td class="p-2.5 font-bold text-emerald-400">Shortest of the Day</td>\n                        <td class="p-2.5">Maximum photosynthesis; animals seek shade</td>\n                    </tr>\n                    <tr class="hover:bg-slate-800/40">\n                        <td class="p-2.5 font-bold text-orange-300">🌇 Evening (Dusk)</td>\n                        <td class="p-2.5">Crimson, purple, orange</td>\n                        <td class="p-2.5">Low on Western horizon</td>\n                        <td class="p-2.5">Very Long • Pointing East</td>\n                        <td class="p-2.5">Birds return to roost; daytime blossoms close</td>\n                    </tr>\n                    <tr class="hover:bg-slate-800/40">\n                        <td class="p-2.5 font-bold text-indigo-300">🌌 Night (Midnight)</td>\n                        <td class="p-2.5">Velvet black with twinkling stars</td>\n                        <td class="p-2.5">Below horizon (Opposite side)</td>\n                        <td class="p-2.5">No solar shadow (Moonlight shadows)</td>\n                        <td class="p-2.5">Owls, bats hunt; nocturnal jasmine blooms</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n    </div>\n    ',
}
